mapper.delete:
DELETE FROM public.chat_history_vector_store
WHERE metadata::jsonb @> CONCAT(
    '{"userWorldId":', #{userWorldId}, ',"characterId":', #{characterId}, '}'
)::jsonb
  AND (metadata::jsonb ->> 'endMessageId')::bigint > #{thresholdEndMessageId}

DELETE FROM public.group_topic_vector_store
WHERE metadata::jsonb @> CONCAT(
    '{"conversationId":', #{conversationId}, '}'
)::jsonb
  AND (metadata::jsonb ->> 'endSequence')::bigint > #{thresholdEndSequence}

DELETE FROM public.group_topic_vector_store
WHERE metadata::jsonb @> CONCAT(
    '{"conversationId":', #{conversationId}, '}'
)::jsonb
  AND (metadata::jsonb ->> 'groupTopicId')::bigint
      > #{maxGroupTopicId}

DELETE FROM public.world_event_vector_store vector
WHERE EXISTS (
    SELECT 1
    FROM world_event_log event
    WHERE event.id = (vector.metadata::jsonb ->> 'worldEventLogId')::bigint
      AND event.conversation_id = #{conversationId}
      AND event.id > #{maxWorldEventLogId}
)
